#!/usr/bin/env python3
"""Publish the reviewed Repaido website from Cloud Shell. No new Cloud Build.

The public website payload is embedded. Credentials are never embedded or saved.
Run: python3 repaido-publish-42cd6f6.py
Offline validation only: python3 repaido-publish-42cd6f6.py --check-only
"""
import argparse
import base64
from datetime import datetime, timezone
import fcntl
import getpass
import hashlib
import importlib.util
import io
import json
import os
from pathlib import Path
import shutil
import subprocess
import sys
import tempfile
import urllib.request
import zipfile

COMMIT = '42cd6f6e8be2d3e244f799450299c9e1b6cf39af'
BUILD = 'e2c9bc0c-acd7-4a06-b96c-156bed812115'
EXPECTED_FILES = {'publisher.py', 'cpanel_client.py', 'initial-state.json',
                  'release.manifest.json', 'baseline.manifest.json',
                  'baseline-asset-sizes.json', 'repaido-42cd6f6-publication.zip'}


def check_bundle():
    raw = base64.b64decode(BUNDLE)
    if hashlib.sha256(raw).hexdigest() != BUNDLE_SHA256:
        raise RuntimeError('Embedded release package failed its integrity check.')
    files = {}
    with zipfile.ZipFile(io.BytesIO(raw)) as archive:
        if set(archive.namelist()) != EXPECTED_FILES or archive.testzip():
            raise RuntimeError('Unexpected or damaged package files.')
        for name in EXPECTED_FILES:
            files[name] = archive.read(name)
    manifest = json.loads(files['release.manifest.json'])
    state = json.loads(files['initial-state.json'])
    assert manifest['commit'] == state['release_commit'] == COMMIT
    assert manifest['required_api_commit'] == COMMIT and state['api_build'] == BUILD
    payload = files['repaido-42cd6f6-publication.zip']
    assert hashlib.sha256(payload).hexdigest() == state['publication_payload_sha256']
    with zipfile.ZipFile(io.BytesIO(payload)) as archive:
        assert set(archive.namelist()) == set(state['publication_paths'])
        assert archive.testzip() is None
        for name in archive.namelist():
            assert hashlib.sha256(archive.read(name)).hexdigest() == manifest['files'][name]
    compile(files['publisher.py'], 'publisher.py', 'exec')
    compile(files['cpanel_client.py'], 'cpanel_client.py', 'exec')
    return files


def prepare(root, files):
    for name, body in files.items():
        path = root / name
        if path.exists():
            if path.read_bytes() != body:
                raise RuntimeError('Existing package file differs: ' + name + '. Keep this folder for diagnosis.')
        else:
            path.write_bytes(body)
            path.chmod(0o600)
    state_path = root / 'state.json'
    if not state_path.exists():
        state = json.loads(files['initial-state.json'])
        state['publication_payload'] = str(root / 'repaido-42cd6f6-publication.zip')
        state_path.write_text(json.dumps(state, indent=2) + '\n')
    else:
        state = json.loads(state_path.read_text())
        assert state['release_commit'] == COMMIT and state['api_build'] == BUILD
        assert state['publication_payload'] == str(root / 'repaido-42cd6f6-publication.zip')
    return state


def cloud_preflight(root):
    if not shutil.which('gcloud'):
        raise RuntimeError('Run this script in authenticated Google Cloud Shell for project repaido.')
    result = subprocess.run(['gcloud', 'builds', 'describe', BUILD, '--project=repaido',
                             '--region=global', '--format=json'], check=True,
                            capture_output=True, text=True, timeout=60)
    build = json.loads(result.stdout)
    assert build['id'] == BUILD and build['status'] == 'SUCCESS', 'Cloud release is not successful.'
    assert build['substitutions']['COMMIT_SHA'] == COMMIT, 'Unexpected cloud source commit.'
    assert build['substitutions']['_RELEASE_APPROVED'] == 'true'
    evidence = {k: build.get(k) for k in ('id', 'status', 'createTime', 'finishTime', 'logUrl')}
    evidence['commit'] = COMMIT
    (root / 'cloud-build-verified.json').write_text(json.dumps(evidence, indent=2) + '\n')
    print('Existing Cloud Build verified. No new build will be started.', flush=True)


def publish(root):
    sys.path.insert(0, str(root))
    spec = importlib.util.spec_from_file_location('repaido_publisher', root / 'publisher.py')
    module = importlib.util.module_from_spec(spec)
    spec.loader.exec_module(module)
    module.health()  # Must still serve the same main/work backend build.
    hosting = json.loads(module.read('https://repaido.web.app/build-info.json?release=' + COMMIT))
    assert hosting['commit'] == COMMIT and hosting['build_id'] == BUILD
    os.environ['CPANEL_HOST'] = 'cpanel.repaido.com'
    os.environ['CPANEL_USERNAME'] = 'repaidoc'
    if not os.environ.get('CPANEL_API_TOKEN'):
        if not sys.stdin.isatty():
            raise RuntimeError('Run interactively so the cPanel API token can be entered privately.')
        token = getpass.getpass('cPanel API token for repaidoc (hidden; not saved): ').strip()
        if not token:
            raise RuntimeError('A cPanel API token is required to publish repaido.com.')
        os.environ['CPANEL_API_TOKEN'] = token
    phase = module.state['website_status']
    # An uncertain upload/backup must be inspected, not blindly repeated.
    if phase in {'backup_in_progress', 'private_payload_uploading'}:
        raise RuntimeError('An earlier staging operation was interrupted. Preserve this folder and share the last output with Codex; do not delete or overwrite the backup.')
    if phase == 'packaged_not_published':
        print('Backing up the current website and staging 11 reviewed assets...', flush=True)
        module.stage()
    elif phase == 'private_payload_extracted':
        module.resume_stage()
    phase = module.state['website_status']
    if phase in {'private_stage_verified_not_published', 'publishing_reviewed_assets',
                 'all_new_assets_hash_verified', 'publishing_entry_and_metadata',
                 'published_pending_canonical_checks'}:
        module.publish()
    elif phase != 'deployed_and_verified':
        raise RuntimeError('Unexpected publication state: ' + phase)
    # Verify canonical URLs after publishing, including both SPA entry routes.
    for path in ('/', '/go?ride=cab', '/worker?mode=driver'):
        body = module.read('https://repaido.com' + path)
        assert hashlib.sha256(body).hexdigest() == module.manifest['files']['index.html'], 'Entry route verification failed: ' + path
    info = json.loads(module.read('https://repaido.com/build-info.json'))
    assert info['commit'] == COMMIT and info['required_api_commit'] == COMMIT
    for path in module.state['publication_paths']:
        assert hashlib.sha256(module.read('https://repaido.com/' + path)).hexdigest() == module.manifest['files'][path], 'Public file verification failed: ' + path
    module.health()
    module.save(website_status='deployed_and_verified', production_verification_completed_at=datetime.now(timezone.utc).isoformat())
    report = {'status': 'PRODUCTION_DEPLOYMENT_COMPLETE', 'website': 'https://repaido.com',
              'commit': COMMIT, 'cloud_build_id': BUILD,
              'verified_at': datetime.now(timezone.utc).isoformat(),
              'backup': module.state['backup_path'], 'evidence_directory': str(root)}
    (root / 'deployment-complete.json').write_text(json.dumps(report, indent=2) + '\n')
    print(json.dumps(report, indent=2), flush=True)


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument('--check-only', action='store_true', help='Validate embedded files only; no network or publication.')
    args = parser.parse_args()
    if sys.flags.optimize:
        raise RuntimeError('Run Python normally, without -O or PYTHONOPTIMIZE.')
    files = check_bundle()
    if args.check_only:
        print('PASS: pinned payload, manifests, all 13 public file hashes and Python source validated. No network calls or website changes.')
        return
    os.umask(0o077)
    root = Path.home() / 'repaido-cpanel-42cd6f6'
    root.mkdir(mode=0o700, exist_ok=True)
    with (root / 'publication.lock').open('a') as lock:
        try:
            fcntl.flock(lock, fcntl.LOCK_EX | fcntl.LOCK_NB)
        except BlockingIOError:
            raise RuntimeError('Another publisher is running for this release. Do not start a duplicate.')
        prepare(root, files)
        cloud_preflight(root)
        publish(root)

